import{_ as t,C as e,o as l,c as d,a4 as n,j as i,E as o}from"./chunks/framework.BUqnS5H7.js";const y=JSON.parse('{"title":"Undo Log","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/02-innodb-internals/chapter-05-undo-log.md","filePath":"mysql/02-innodb-internals/chapter-05-undo-log.md"}'),r={name:"mysql/02-innodb-internals/chapter-05-undo-log.md"},c={"data-src-line":"7","data-src-file":"mysql/02-innodb-internals/chapter-05-undo-log.md"};function p(h,a,g,u,m,k){const s=e("SvgDiagram");return l(),d("div",null,[a[0]||(a[0]=n('<h1 id="undo-log" tabindex="-1" data-src-line="1" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Undo Log <a class="header-anchor" href="#undo-log" aria-label="Permalink to &quot;Undo Log&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><p data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">一条 <code>DELETE</code> 之后立刻 <code>ROLLBACK</code>，被删的行又回来了。InnoDB 没给每张表做「删除前的备份」，它凭什么能精确撤销？凭的是一份「逆向操作」日志——Undo Log。同一份日志还顺手撑起了 MVCC 的无锁读：它同时是「回滚的依据」和「历史版本的仓库」。</p></blockquote><h2 id="_1-undo-log-是什么" tabindex="-1" data-src-line="5" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">1. Undo Log 是什么 <a class="header-anchor" href="#_1-undo-log-是什么" aria-label="Permalink to &quot;1. Undo Log 是什么&quot;">​</a></h2>',3)),i("p",c,[o(s,{src:"/mysql/02-innodb-internals-chapter-05-undo-log.svg",alt:"Undo Log 全景：逆向操作日志 + MVCC 版本链载体"})]),a[1]||(a[1]=n(`<h3 id="_1-1-从一次回滚说起" tabindex="-1" data-src-line="9" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">1.1 从一次回滚说起 <a class="header-anchor" href="#_1-1-从一次回滚说起" aria-label="Permalink to &quot;1.1 从一次回滚说起&quot;">​</a></h3><p data-src-line="11" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">先建立一个具体场景：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 500 → 400</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ... 发现扣错了账户</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ROLLBACK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- balance 回到 500</span></span></code></pre></div><p data-src-line="21" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><code>ROLLBACK</code> 之后，<code>id=1</code> 的余额精确回到 500，而不是「大致回到某个旧值」。这意味着 InnoDB 在 <code>UPDATE</code> 执行的那一刻，就把「改回去需要的信息」记了下来。这份记录就是 Undo Log。</p><p data-src-line="23" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Undo Log 与 Redo Log 是两份目的相反的日志：</p><table tabindex="0"><thead data-src-line="25" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><tr data-src-line="25" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><th style="text-align:left;">对比项</th><th style="text-align:left;">Undo Log</th><th style="text-align:left;">Redo Log</th></tr></thead><tbody data-src-line="27" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><tr data-src-line="27" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><td style="text-align:left;">记录内容</td><td style="text-align:left;"><strong>逆向操作</strong>（如何改回去）</td><td style="text-align:left;"><strong>正向操作</strong>（改了什么）</td></tr><tr data-src-line="28" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><td style="text-align:left;">逻辑/物理</td><td style="text-align:left;">逻辑日志</td><td style="text-align:left;">物理日志</td></tr><tr data-src-line="29" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><td style="text-align:left;">服务对象</td><td style="text-align:left;">回滚 + MVCC</td><td style="text-align:left;">崩溃恢复</td></tr><tr data-src-line="30" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><td style="text-align:left;">生命周期</td><td style="text-align:left;">事务提交后由 Purge 延迟清理</td><td style="text-align:left;">循环写，固定大小</td></tr></tbody></table><p data-src-line="32" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">一句话区分：<strong>Redo 保证「改过的不会丢」，Undo 保证「改错的能改回」。</strong> 前者见 <a href="./chapter-04-redo-log.html">Redo Log</a>，本章聚焦后者。</p><h3 id="_1-2-undo-log-记录的不是数据快照-是「逆向操作」" tabindex="-1" data-src-line="34" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">1.2 Undo Log 记录的不是数据快照，是「逆向操作」 <a class="header-anchor" href="#_1-2-undo-log-记录的不是数据快照-是「逆向操作」" aria-label="Permalink to &quot;1.2 Undo Log 记录的不是数据快照，是「逆向操作」&quot;">​</a></h3><p data-src-line="36" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Undo Log 是<strong>逻辑日志</strong>，它不复制整行数据，而是记录「如何撤销这次修改」。同样是把 <code>balance</code> 从 500 改成 400，Undo Log 记录的语义是「把这一行的 balance 加 100」，而不是「旧值是 500」。</p><p data-src-line="38" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">这个区别决定了 Undo Log 的体积和用途：</p><ul data-src-line="40" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><li data-src-line="40" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>体积小</strong>：只记操作指令，不复制整页；</li><li data-src-line="41" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>可回放</strong>：回滚时执行逆向操作即可；</li><li data-src-line="42" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>可被 MVCC 复用</strong>：记录里保留了旧字段值，旧版本正是从这些逆向信息里重建出来的。</li></ul><p data-src-line="44" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">一条 <code>UPDATE</code> 产生的 Undo 记录，大致包含这些内容：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Undo 记录（简化）</span></span>
<span class="line"><span>├─ undo_no         本次操作在事务内的序号</span></span>
<span class="line"><span>├─ 表 ID / 主键     定位到哪一行</span></span>
<span class="line"><span>├─ 被修改的列及旧值   balance 的旧值 500（用于回滚和 MVCC）</span></span>
<span class="line"><span>└─ 指向前一条 Undo   构成同事务内的 Undo 链</span></span></code></pre></div><p data-src-line="54" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">事务内连续多次修改同一行，会形成一条事务内部的 Undo 链；而不同事务对同一行的修改，则通过行记录里的 <code>DB_ROLL_PTR</code> 串成跨事务的<strong>版本链</strong>（见 §3.1）。</p><h2 id="_2-两类-undo-与存储位置" tabindex="-1" data-src-line="56" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">2. 两类 Undo 与存储位置 <a class="header-anchor" href="#_2-两类-undo-与存储位置" aria-label="Permalink to &quot;2. 两类 Undo 与存储位置&quot;">​</a></h2><h3 id="_2-1-两类-undo-insert-undo-与-update-undo" tabindex="-1" data-src-line="58" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">2.1 两类 Undo：insert undo 与 update undo <a class="header-anchor" href="#_2-1-两类-undo-insert-undo-与-update-undo" aria-label="Permalink to &quot;2.1 两类 Undo：insert undo 与 update undo&quot;">​</a></h3><p data-src-line="60" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Undo Log 按「回滚需要做什么」分为两类，它们的清理时机完全不同：</p><table tabindex="0"><thead data-src-line="62" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><tr data-src-line="62" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><th style="text-align:left;">类型</th><th style="text-align:left;">由什么操作产生</th><th style="text-align:left;">回滚动作</th><th style="text-align:left;">清理时机</th></tr></thead><tbody data-src-line="64" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><tr data-src-line="64" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><td style="text-align:left;"><strong>insert undo</strong></td><td style="text-align:left;"><code>INSERT</code></td><td style="text-align:left;">删除插入的行</td><td style="text-align:left;">事务提交后即可清理</td></tr><tr data-src-line="65" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><td style="text-align:left;"><strong>update undo</strong></td><td style="text-align:left;"><code>UPDATE</code> / <code>DELETE</code></td><td style="text-align:left;">把行改回旧值</td><td style="text-align:left;">等所有 Read View 不再需要后由 Purge 清理</td></tr></tbody></table><p data-src-line="67" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>为什么 insert undo 能随事务结束直接删，update undo 却要等？</strong></p><p data-src-line="69" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">关键在「这行数据对别的事务可不可见」。</p><ul data-src-line="71" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><li data-src-line="71" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><p data-src-line="71" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><code>INSERT</code> 插入的是<strong>新行</strong>。在这行插入之前，任何早于该事务开始的其他事务，都不可能通过它们的 Read View 看到这行（这行对它们是「未来」才出现的）。既然没人看见过它，回滚时直接删掉即可，也不需要为「历史版本」保留它。所以 insert undo 在事务提交后，没有其他事务需要它，可立即清理。</p></li><li data-src-line="73" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><p data-src-line="73" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><code>UPDATE</code> / <code>DELETE</code> 修改的是<strong>已存在的行</strong>。这行的旧值，可能正被某个并发事务的 Read View 引用（那个事务需要一个「修改前」的版本才能做到可重复读）。因此旧值必须保留，直到<strong>所有可能看见它的 Read View 都结束</strong>，才能删。</p></li></ul><p data-src-line="75" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">这就是「同一份 Undo Log，两类记录，两套生命周期」的由来。也解释了为什么频繁 <code>INSERT</code> 的表 Undo 压力小，而频繁 <code>UPDATE</code> / <code>DELETE</code> 的表 Undo 容易堆积。</p><h3 id="_2-2-undo-log-存在哪里-回滚段与-undo-表空间" tabindex="-1" data-src-line="77" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">2.2 Undo Log 存在哪里：回滚段与 Undo 表空间 <a class="header-anchor" href="#_2-2-undo-log-存在哪里-回滚段与-undo-表空间" aria-label="Permalink to &quot;2.2 Undo Log 存在哪里：回滚段与 Undo 表空间&quot;">​</a></h3><p data-src-line="79" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Undo Log 不是独立于表空间的文件，它存放在**回滚段（Rollback Segment）**里。回滚段是 Undo 页的组织单元，一个回滚段管理一串 Undo 页链表。</p><p data-src-line="81" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">MySQL 8.0 默认配置下：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Undo 表空间数量（默认 2 个：undo_001、undo_002）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_undo_tablespaces&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 单个 Undo 表空间的最大大小（默认 1GB，超过会自动截断）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_max_undo_log_size&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 是否开启 Undo 表空间自动截断（默认 ON）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_undo_log_truncate&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">版本锚点</p><p data-src-line="95" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">MySQL 5.6 之前，Undo Log 存放在系统表空间 <code>ibdata1</code> 里，无法独立回收；5.6 起可配置独立 Undo 表空间；8.0 起默认使用独立 Undo 表空间，并支持自动截断。</p></div><p data-src-line="98" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">一个 Undo 页的内部结构：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────┐</span></span>
<span class="line"><span>│ Undo Page Header │  页元信息（链表指针等）</span></span>
<span class="line"><span>├──────────────────┤</span></span>
<span class="line"><span>│ Undo Record      │  一条逆向操作记录</span></span>
<span class="line"><span>├──────────────────┤</span></span>
<span class="line"><span>│ Undo Record      │  ...</span></span>
<span class="line"><span>├──────────────────┤</span></span>
<span class="line"><span>│ Free Space       │</span></span>
<span class="line"><span>└──────────────────┘</span></span></code></pre></div><p data-src-line="112" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">多个事务的 Undo 记录可以共享同一个回滚段、同一组 Undo 页，通过链表串起来。这里的存储细节不需要全部记住，需要理解的是：<strong>Undo Log 占用的是独立空间，且这段空间只有在 Purge 清理后才会真正释放。</strong></p><h2 id="_3-版本链-mvcc-的载体" tabindex="-1" data-src-line="114" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">3. 版本链：MVCC 的载体 <a class="header-anchor" href="#_3-版本链-mvcc-的载体" aria-label="Permalink to &quot;3. 版本链：MVCC 的载体&quot;">​</a></h2><h3 id="_3-1-版本链-undo-的另一半用途" tabindex="-1" data-src-line="116" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">3.1 版本链：Undo 的另一半用途 <a class="header-anchor" href="#_3-1-版本链-undo-的另一半用途" aria-label="Permalink to &quot;3.1 版本链：Undo 的另一半用途&quot;">​</a></h3><p data-src-line="118" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Undo Log 除了回滚，还支撑 MVCC。 <a href="./../04-transaction-lock/chapter-01-transaction.html#version-chain">事务与 MVCC §2.3</a> 已经详细讲过：每行记录的 <code>DB_ROLL_PTR</code> 指向 Undo 中的旧版本，多次修改串成一条从当前版本通到最老版本的链。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前记录 → Undo v3 → Undo v2 → Undo v1</span></span>
<span class="line"><span>(trx=105)  (trx=104) (trx=102) (trx=101)</span></span></code></pre></div><p data-src-line="125" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">快照读时，事务沿这条链，用 Read View 判定每个版本是否可见。<strong>版本链与可见性判定的完整算法见 <a href="./../04-transaction-lock/chapter-01-transaction.html#visibility-judgment">事务与 MVCC §3.2</a>，本文不再重复。</strong> 这里只强调 Undo 视角下的一个推论：</p><blockquote data-src-line="127" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><p data-src-line="127" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">每一条 Undo 记录，都被两类对象「引用」——<strong>回滚时的事务</strong>，以及<strong>可能看见这个旧版本的 Read View</strong>。只有当两类引用都消失，这条 Undo 才能被 Purge 安全删除。</p></blockquote><p data-src-line="129" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">这个「双引用」事实，是理解下一节 Purge 时机的钥匙。</p><h2 id="_4-删除、清理与膨胀" tabindex="-1" data-src-line="131" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">4. 删除、清理与膨胀 <a class="header-anchor" href="#_4-删除、清理与膨胀" aria-label="Permalink to &quot;4. 删除、清理与膨胀&quot;">​</a></h2><h3 id="_4-1-delete-是「假删除」-delete-mark" tabindex="-1" data-src-line="133" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">4.1 DELETE 是「假删除」：delete mark <a class="header-anchor" href="#_4-1-delete-是「假删除」-delete-mark" aria-label="Permalink to &quot;4.1 DELETE 是「假删除」：delete mark&quot;">​</a></h3><p data-src-line="135" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><code>DELETE</code> 产生的 update undo，牵扯一个容易误解的细节：<strong>InnoDB 的 <code>DELETE</code> 并不是立刻把行从页里抹掉</strong>，而是先做一次<strong>删除标记（delete mark）</strong>——在记录头上打一个「已删除」标志，行数据仍留在原地。</p><p data-src-line="137" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">真正的物理删除，要等到 Purge 阶段才执行。这样设计的原因：</p><ol data-src-line="139" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><li data-src-line="139" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>回滚需要</strong>：如果事务还没提交，随时可能要 <code>ROLLBACK</code>，此时只需清除删除标记即可恢复；</li><li data-src-line="140" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>MVCC 需要</strong>：其他事务的 Read View 可能还要读这行的旧版本，物理删除会让它们读不到。</li></ol><p data-src-line="142" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">所以 <code>DELETE</code> 之后磁盘空间不会立即变小，要等 Purge 真正清理，空间才释放。这是「删了数据，磁盘占用却没降」这一常见现象的根因。</p><h3 id="_4-2-purge-谁来清理、何时清理" tabindex="-1" data-src-line="144" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">4.2 Purge：谁来清理、何时清理 <a class="header-anchor" href="#_4-2-purge-谁来清理、何时清理" aria-label="Permalink to &quot;4.2 Purge：谁来清理、何时清理&quot;">​</a></h3><p data-src-line="146" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Purge 线程（一组后台线程）负责清理「不再需要」的 Undo 记录。它要判断两类 Undo 分别何时可删：</p><ul data-src-line="148" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><li data-src-line="148" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>insert undo</strong>：对应事务已提交即可删（原因见 §2.1）；</li><li data-src-line="149" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>update undo</strong>：对应事务已提交，<strong>且</strong>不存在任何 Read View 还需要这个旧版本。</li></ul><p data-src-line="151" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">第二条判断的执行方式是：Purge 维护一个「最老的活跃 Read View」，只要某条 update undo 的 <code>trx_id</code> 比这个最老 Read View 的 <code>min_trx_id</code> 还小（即早于所有可能看见它的读视图），就能安全清理。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Purge 线程数（默认 4）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_purge_threads&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Purge 落后阈值（默认 0，表示不限制）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_max_purge_lag&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p data-src-line="161" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">当 Purge 追不上 Undo 的产生速度时，Undo 空间会持续膨胀。<code>innodb_max_purge_lag</code> 非 0 时，InnoDB 会在 Purge 落后超过阈值后对 DML 限流——通过让写操作「等一等 Purge」来给清理腾出时间，避免磁盘被 Undo 撑满。</p><h3 id="_4-3-长事务-undo-膨胀的元凶" tabindex="-1" data-src-line="163" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">4.3 长事务：Undo 膨胀的元凶 <a class="header-anchor" href="#_4-3-长事务-undo-膨胀的元凶" aria-label="Permalink to &quot;4.3 长事务：Undo 膨胀的元凶&quot;">​</a></h3><p data-src-line="165" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">结合 §4.2 的清理条件，就能推出一个反直觉的结论：<strong>一条已经提交、甚至早已结束的 update undo，可能因为一个「还没结束的长事务」而迟迟无法被 Purge。</strong></p><p data-src-line="167" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">原因：那个长事务持有「很老」的 Read View，它的 <code>min_trx_id</code> 停在很久以前。Purge 判定时，凡是 <code>trx_id</code> 大于这个 <code>min_trx_id</code> 的 update undo 都被认为「可能被看见」，一律保留。于是：</p><ul data-src-line="169" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><li data-src-line="169" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">长事务之后产生的所有 update undo 全部堆积；</li><li data-src-line="170" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">Undo 表空间持续增长，逼近甚至突破 <code>innodb_max_undo_log_size</code>；</li><li data-src-line="171" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">版本链变长，快照读要走更多步才能定位可见版本，查询变慢；</li><li data-src-line="172" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">事务本身若还持有行锁，还会连带阻塞其他事务。</li></ul><p data-src-line="174" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">排查手段与「避免长事务」的完整清单见 <a href="./../04-transaction-lock/chapter-01-transaction.html#long-transaction">事务与 MVCC §4.3</a>。</p><h2 id="_5-最佳实践" tabindex="-1" data-src-line="176" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md">5. 最佳实践 <a class="header-anchor" href="#_5-最佳实践" aria-label="Permalink to &quot;5. 最佳实践&quot;">​</a></h2><ol data-src-line="178" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><li data-src-line="178" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>避免长事务</strong>：这是控制 Undo 体积的第一优先级，见 §4.3。</li><li data-src-line="179" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>大批量删除分批执行</strong>：把一次 <code>DELETE</code> 大量行拆成多个小事务，缩短单条 Undo 链，给 Purge 留出节奏。</li><li data-src-line="180" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>监控 Undo 与 Purge 状态</strong>：<code>SHOW GLOBAL STATUS LIKE &#39;Innodb_undo%&#39;;</code> 观察 Undo 页数量；关注 Purge 是否落后。</li><li data-src-line="181" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>高并发读场景可考虑 <code>READ COMMITTED</code></strong>：Read View 每次重建，生命周期短，Undo 清理更及时，见 <a href="./../04-transaction-lock/chapter-01-transaction.html#rr-rc-read-view">事务与 MVCC §3.3</a>。</li><li data-src-line="182" data-src-file="mysql/02-innodb-internals/chapter-05-undo-log.md"><strong>理解 DELETE 的「假删除」</strong>：删除后磁盘不立刻释放是正常现象，不必恐慌，等 Purge 处理即可。</li></ol>`,56))])}const f=t(r,[["render",p]]);export{y as __pageData,f as default};
